import{_ as i,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"重试与幂等","description":"","frontmatter":{"title":"重试与幂等","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/retry-idempotency.md","filePath":"cs/retry-idempotency.md","lastUpdated":1789023840000}'),h={name:"cs/retry-idempotency.md"};function E(T,a,m,_,u,f){const o=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="重试与幂等" tabindex="-1">重试与幂等 <a class="header-anchor" href="#重试与幂等" aria-label="Permalink to &quot;重试与幂等&quot;">​</a></h1><div class="epigraph"><p>超时后重试可能让「一次」变成「两次」；只有幂等或带幂等键的请求才能自动重放，否则要业务去重。</p><footer>—— 据 RFC 9110 方法幂等；gRPC retry 实践整理</footer></div><p><a href="/cs/http-semantics">HTTP 语义</a> 已钉 GET 幂等。<a href="/cs/heartbeat-timeout">心跳超时</a> 触发重试。<a href="/cs/quic-streams-0rtt">QUIC 0-RTT</a> 有重放。<a href="/cs/heartbeat-timeout">上一课</a> 留下失败之后。缺口是<strong>何时可自动重试</strong>。本课不把背压写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LB 摘除、无线丢、超时：客户端想再来一次。GET/PUT 幂等可重试；POST 扣款不行，除非 Idempotency-Key。指数退避 + 抖动防惊群（与 TCP RTO 同形）。gRPC 可对 UNAVAILABLE 重试。0-RTT 只给安全方法。服务端必须去重，因「至少一次」交付。</p><p>不要把 TCP 重传算作应用重试：那是同一段。</p><p><span class="marginnote">RFC 9110。键的存储寿命要覆盖重试窗。</span></p><h3 id="运输重传不是应用重试" tabindex="-1">运输重传不是应用重试 <a class="header-anchor" href="#运输重传不是应用重试" aria-label="Permalink to &quot;运输重传不是应用重试&quot;">​</a></h3><p>GET 可自动放；POST 要键或去重。退避加抖动有上限。无限重试是自我 DoS。0-RTT 只给安全方法。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：至少一次 / 至多一次 / 恰好一次（难）。画：失败 → 是否幂等 → 退避重试。与 SYN 重传对照。</p>',11)),(e(),n(c,null,{default:r(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E8%B6%85%E6%97%B6%E6%88%96%E9%94%99%E8%AF%AF%22%5D%20--%3E%20IDEM%5B%22%E6%98%AF%E5%90%A6%E5%B9%82%E7%AD%89%22%5D%0A%20%20IDEM%20--%3E%20RET%5B%22%E9%80%80%E9%81%BF%E9%87%8D%E8%AF%95%22%5D%0A%20%20IDEM%20--%3E%20APP%5B%22%E4%B8%9A%E5%8A%A1%E5%8E%BB%E9%87%8D%2F%E6%94%BE%E5%BC%83%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向代理重试 GET 要防非幂等被标错方法。Maglev 换后端可能双处理。DNS 切换中重试打到新旧两源。邮件 SMTP 已有队列重试，要 DSN。</p><p>安全：重试放大失败成洪泛，要预算。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 saga 补偿的全部。应用层背压是下一课。后课默认：自动重试仅幂等；否则键或人工。</p><p>无限重试等于自己做 DoS。</p><p>上一课留下的缺口在本课收口；「重试与幂等」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/app-backpressure">应用层背压</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>运输重传 ≠ 应用重试。</li><li>幂等或幂等键才能自动放。</li><li>退避加抖动，且有上限。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9110；RPC 实践。</li></ul>',10))])}const b=i(h,[["render",E]]);export{A as __pageData,b as default};
